const evento = `
BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//Ekinoxis//Cali Business Hub//ES
CALSCALE:GREGORIAN
BEGIN:VEVENT
UID:${$json.referencia || 'sin-ref'}@calibusinesshub.com
DTSTAMP:${new Date().toISOString().replace(/[-:]/g, '').split('.')[0]}Z
DTSTART:20251206T140000Z
DTEND:20251206T210000Z
SUMMARY:CALI BUSINESS HUB 2025
DESCRIPTION:Tu registro ha sido confirmado.\n\nEvento empresarial para conectar emprendedores e inversionistas.\n\nMás info en https://calibusinesshub.com
LOCATION:Zona América, Cali, Colombia
STATUS:CONFIRMED
END:VEVENT
END:VCALENDAR
`;

return [
  {
    json: {
      ...$json,
      mensaje: 'Archivo .ics generado correctamente',
      nombre_archivo: `CaliBusinessHub_${$json.referencia || 'entrada'}.ics`
    },
    binary: {
      data: {
        data: Buffer.from(evento).toString('base64'),
        mimeType: 'text/calendar',
        fileName: `CaliBusinessHub_${$json.referencia || 'entrada'}.ics`
      }
    }
  }
];
